nextflow_process {

    name "Test Process ANTISMASH_ANTISMASHLITEDOWNLOADDATABASES"
    script "../main.nf"
    process "ANTISMASH_ANTISMASHLITEDOWNLOADDATABASES"

    tag "modules"
    tag "modules_nfcore"
    tag "antismash"
    tag "antismash/antismashlitedownloaddatabases"

    test("deprecated") {

        when {
            process {
                """
                input[0] = file('database_css')
                input[1] = file('database_detection')
                input[2] = file('database_modules')
                """
            }
        }

        then {
            assertAll(
                { assert process.failed },
                { assert process.errorReport.contains("WARNING: This module has been deprecated. Please use nf-core/modules/antismash/antismashdownloaddatabases") }
            )
        }
    }
}
